package main

import (
	"fmt"
	"os"
	"strconv"
	"strings"

	"github.com/shopspring/decimal"
)

type DiscRec struct {
	DrItem  string          // PIC X(6) @0 len=6
	DrPrice decimal.Decimal // PIC 9(5)V99 @6 len=7
	DrPct   int64           // PIC 9(2) @13 len=2
}

var WsEofFlag string = "N"
var WsDiscount decimal.Decimal = decimal.Zero
var WsNet decimal.Decimal = decimal.Zero
var WsTotalNet decimal.Decimal = decimal.Zero
var WsCount int64 = 0
var WsPriceEd string
var WsDiscEd string
var WsNetEd string
var WsTotalEd string

var discRec DiscRec
var inputLines []string
var inputIdx int

func isInputDone() bool { return WsEofFlag == "Y" }

func pow10Int64(n int) int64 {
	var p int64 = 1
	for i := 0; i < n; i++ {
		p *= 10
	}
	return p
}

func parsePrice(s string) decimal.Decimal {
	var b strings.Builder
	for _, ch := range s {
		if ch >= '0' && ch <= '9' {
			b.WriteRune(ch)
		} else {
			b.WriteRune('0')
		}
	}
	digits := b.String()
	if digits == "" {
		digits = "0"
	}
	d, err := decimal.NewFromString(digits)
	if err != nil {
		d = decimal.Zero
	}
	d = d.Shift(-2)
	return d
}

func parsePct(s string) int64 {
	var b strings.Builder
	for _, ch := range s {
		if ch >= '0' && ch <= '9' {
			b.WriteRune(ch)
		} else {
			b.WriteRune('0')
		}
	}
	digits := b.String()
	if digits == "" {
		return 0
	}
	v, _ := strconv.ParseInt(digits, 10, 64)
	return v
}

// round half away from zero to scale
func roundHalfAway(d decimal.Decimal, scale int32) decimal.Decimal {
	shifted := d.Shift(scale)
	intPart := shifted.Truncate(0)
	frac := shifted.Sub(intPart).Abs()
	half := decimal.NewFromInt(5).Shift(-1) // 0.5
	if frac.Cmp(half) < 0 {
		return intPart.Shift(-scale)
	}
	if d.Sign() >= 0 {
		intPart = intPart.Add(decimal.NewFromInt(1))
	} else {
		intPart = intPart.Sub(decimal.NewFromInt(1))
	}
	return intPart.Shift(-scale)
}

func storeDecimal(val decimal.Decimal, intDigits, scale int) decimal.Decimal {
	vTrunc := val.Truncate(int32(scale))
	neg := vTrunc.Sign() < 0
	abs := vTrunc.Abs()
	scaled := abs.Shift(int32(scale)).Truncate(0)
	powTotal := decimal.NewFromInt(1).Shift(int32(intDigits + scale))
	if scaled.Cmp(powTotal) >= 0 {
		rem := scaled.Mod(powTotal)
		res := rem.Shift(int32(-scale))
		if neg {
			res = res.Neg()
		}
		return res
	}
	return vTrunc
}

func formatEdited(val decimal.Decimal, pic string) string {
	dotIdx := strings.Index(pic, ".")
	var leftPic, rightPic string
	if dotIdx >= 0 {
		leftPic = pic[:dotIdx]
		rightPic = pic[dotIdx+1:]
	} else {
		leftPic = pic
		rightPic = ""
	}
	decCount := len(rightPic)
	intCap := 0
	for _, ch := range leftPic {
		if ch == 'Z' || ch == '9' {
			intCap++
		}
	}
	isNeg := val.Sign() < 0
	absVal := val.Abs()
	absTrunc := absVal.Truncate(int32(decCount))
	scaled := absTrunc.Shift(int32(decCount)).Truncate(0)
	scaledInt := scaled.IntPart()
	var intPart, fracPart int64
	if decCount > 0 {
		powDec := pow10Int64(decCount)
		intPart = scaledInt / powDec
		fracPart = scaledInt % powDec
	} else {
		intPart = scaledInt
		fracPart = 0
	}
	powIntCap := pow10Int64(intCap)
	if intCap > 0 && intPart >= powIntCap {
		intPart = intPart % powIntCap
	}
	intStr := fmt.Sprintf("%0*d", intCap, intPart)

	// positions of placeholders
	phPos := []int{}
	for i, ch := range leftPic {
		if ch == 'Z' || ch == '9' {
			phPos = append(phPos, i)
		}
	}
	firstSig := intCap
	for idx := 0; idx < intCap; idx++ {
		ch := rune(leftPic[phPos[idx]])
		digit := intStr[idx]
		if ch == '9' {
			firstSig = idx
			break
		}
		if digit != '0' {
			firstSig = idx
			break
		}
	}
	// build left result
	leftResult := make([]byte, len(leftPic))
	posToIdx := make(map[int]int)
	for idx, pos := range phPos {
		posToIdx[pos] = idx
	}
	for i := 0; i < len(leftPic); i++ {
		ch := leftPic[i]
		if ch == 'Z' || ch == '9' {
			idx := posToIdx[i]
			digit := intStr[idx]
			if idx < firstSig {
				leftResult[i] = ' '
			} else {
				leftResult[i] = byte(digit)
			}
		} else if ch == ',' {
			cntBefore := 0
			for _, pos := range phPos {
				if pos < i {
					cntBefore++
				}
			}
			maxIdxBefore := cntBefore - 1
			if maxIdxBefore >= firstSig && maxIdxBefore >= 0 {
				leftResult[i] = ','
			} else {
				leftResult[i] = ' '
			}
		} else {
			leftResult[i] = byte(ch)
		}
	}
	if isNeg && intCap > 0 && firstSig < intCap {
		posFirst := phPos[firstSig]
		placed := false
		for j := posFirst - 1; j >= 0; j-- {
			if leftResult[j] == ' ' {
				leftResult[j] = '-'
				placed = true
				break
			}
		}
		if !placed {
			// no space, overwrite first position if possible
			if len(leftResult) > 0 {
				leftResult[0] = '-'
			}
		}
	}
	leftStr := string(leftResult)
	if decCount > 0 {
		fracStr := fmt.Sprintf("%0*d", decCount, fracPart)
		return leftStr + "." + fracStr
	}
	return leftStr
}

func openDiscFile() {
	data, err := os.ReadFile("input.dat")
	if err != nil {
		if os.IsNotExist(err) {
			inputLines = []string{}
			return
		}
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	if len(data) == 0 {
		inputLines = []string{}
		return
	}
	s := string(data)
	s = strings.ReplaceAll(s, "\r\n", "\n")
	s = strings.ReplaceAll(s, "\r", "\n")
	lines := strings.Split(s, "\n")
	if strings.HasSuffix(s, "\n") {
		if len(lines) > 0 && lines[len(lines)-1] == "" {
			lines = lines[:len(lines)-1]
		}
	}
	inputLines = lines
}

func readPara() {
	if inputIdx >= len(inputLines) {
		WsEofFlag = "Y"
		return
	}
	line := inputLines[inputIdx]
	inputIdx++
	if len(line) < 15 {
		line = line + strings.Repeat(" ", 15-len(line))
	} else if len(line) > 15 {
		line = line[:15]
	}
	discRec.DrItem = line[0:6]
	discRec.DrPrice = parsePrice(line[6:13])
	discRec.DrPct = parsePct(line[13:15])
}

func processPara() {
	raw := discRec.DrPrice.Mul(decimal.NewFromInt(discRec.DrPct)).Shift(-2)
	rounded := roundHalfAway(raw, 2)
	WsDiscount = storeDecimal(rounded, 5, 2)

	netRaw := discRec.DrPrice.Sub(WsDiscount)
	WsNet = storeDecimal(netRaw, 5, 2)

	totalRaw := WsTotalNet.Add(WsNet)
	WsTotalNet = storeDecimal(totalRaw, 8, 2)

	WsCount = (WsCount + 1) % 1000

	WsPriceEd = formatEdited(discRec.DrPrice, "ZZ,ZZ9.99")
	WsDiscEd = formatEdited(WsDiscount, "ZZ,ZZ9.99")
	WsNetEd = formatEdited(WsNet, "ZZ,ZZ9.99")

	pctStr := fmt.Sprintf("%02d", discRec.DrPct)
	fmt.Printf("%s %s %s%% %s %s\n", discRec.DrItem, WsPriceEd, pctStr, WsDiscEd, WsNetEd)

	readPara()
}

func summaryPara() {
	WsTotalEd = formatEdited(WsTotalNet, "ZZ,ZZZ,ZZ9.99")
	cntStr := fmt.Sprintf("%03d", WsCount)
	fmt.Printf("ITEMS: %s NET TOTAL: %s\n", cntStr, WsTotalEd)
}

func mainPara() {
	openDiscFile()
	readPara()
	for !isInputDone() {
		processPara()
	}
	summaryPara()
}

func main() {
	mainPara()
}
